csui.define('csui/controls/pagination/nodespagination.view',[
  'nuc/lib/underscore',
  'csui/behaviors/keyboard.navigation/tabable.region.behavior',
  'smart/controls/pagination/nodespagination.view'
], function (_, TabableRegionBehavior, SmartPaginationView) {
  var NodesPaginationView = SmartPaginationView.extend({
    behaviors: {
      TabableRegion: {
        behaviorClass: TabableRegionBehavior
      }
    },

    constructor: function NodesPaginationView(options) {
      if (options.collection) {
        this.listenTo(options.collection, 'collection:set:limit', _.bind(this.collectionReset, this));
      }
      SmartPaginationView.prototype.constructor.call(this, options);
    },

    /**
     * @param skipItems
     * @param pageSize
     * @param autoFetch
     * Set the new offset to the children collection and let it load new data from server.
     Note: the view is rendered automatically when the collection gets filled with new data, because in the constructor we registered on the reset event at the collection
     */
    collectionReset: function (resetObj) {
      this.collection.setLimit(resetObj.skipItems, resetObj.pageSize, resetObj.autoFetch, resetObj.paginationView);
    }

  });

  return NodesPaginationView;
});
