csui.define('csui/widgets/permissions/dynamic.permissions/header.action.items.masks',['module',
    'csui/controls/toolbar/toolitems.mask',
    'csui/utils/toolitem.masks/global.toolitems.mask'
  ], function (module, ToolItemMask, GlobalMenuItemsMask) {
    'use strict';
  
    let toolbars = ['dropdownMenuList'];
  
    function HeaderActionItemsMasks() {
      let config = module.config();
      let globalMask = new GlobalMenuItemsMask();
      // Create and populate masks for every toolbar
      this.toolbars = toolbars.reduce(function (toolbars, toolbar) {
        let mask = new ToolItemMask(globalMask, { normalize: false });
        // Masks passed in by separate require.config calls are sub-objects
        // stored in the outer object be different keys
        Object.entries(config).forEach(([key, source]) => {
          source = source[toolbar];
          if (source) {
            mask.extendMask(source);
          }
        });
        // Enable restoring the mask to its initial state
        mask.storeMask();
        toolbars[toolbar] = mask;
        return toolbars;
      }, {});
    }
  
    HeaderActionItemsMasks.toolbars = toolbars;
  
    return HeaderActionItemsMasks;
  });