csui.define('csui/controls/table/cells/description/description.view',['csui/controls/table/cells/templated/templated.view',
  'csui/controls/table/cells/cell.registry',
  'i18n!csui/controls/table/impl/nls/lang',
  'hbs!csui/controls/table/cells/description/impl/description',
  'css!csui/controls/table/cells/description/impl/description',
], function (TemplatedCellView, cellViewRegistry, lang, template) {

  var DescriptionCellView = TemplatedCellView.extend({

    template: template,

    renderValue: function () {
      var text = this.getValueText();
      var isEmpty = text === undefined || text.length === 0;
      var html = this.template({value: text, isEmpty: isEmpty});
      this.$el.html(html);
    }

  }, {
    hasFixedWidth: false,
    columnClassName: 'csui-table-cell-description'
  });

  cellViewRegistry.registerByColumnKey('description', DescriptionCellView);

  return DescriptionCellView;

});
