csui.define('csui/utils/dragndrop.supported.subtypes',[
  'csui/lib/underscore',
  // Load and register external drag and drop supported subtyes
  'csui-ext!csui/utils/dragndrop.supported.subtypes'
], function (_, ExtraDragNDropSupportedSubTypes) {
  'use strict';
  // Default drag and drop supported subtypes
  // 0: folder, 202: project, 751: Email Folder, 30205: CompoundDocument, 144: Document,
  //136: CompoundDocument, 141: Enterprise Workspace, 142: My Workspace,
  // 800: Intelligent filing folder, 801: Document (to be filled)
  // 1307: Support Asset, 1308: Support Asset Folder
  var DragNDropSupportedSubTypes = [
    0, 136, 141, 142, 144, 202, 749, 751, 800, 801, 1307, 1308, 30205
  ];

  if (ExtraDragNDropSupportedSubTypes) {
    DragNDropSupportedSubTypes = DragNDropSupportedSubTypes.concat(
        _.flatten(ExtraDragNDropSupportedSubTypes, true));
  }

  return DragNDropSupportedSubTypes;

});