csui.define('csui/widgets/permissions/dynamic.permissions/header.action.items',[
  "csui/controls/toolbar/toolitems.factory",
  "csui/controls/toolbar/toolitem.model",
  // Load extra tool items to be added to this collection
  "csui-ext!csui/widgets/permissions/dynamic.permissions/header.action.items",
], function (ToolItemsFactory, TooItemModel, extraToolItems) {
  "use strict";

  let toolbarItems = {
    dropdownMenuList: new ToolItemsFactory(
      {
        main: [],
      },
      {
        maxItemsShown: 0,
        dropDownIconName: "csui_action:action_add32"
      }
    ),
  };

  if (extraToolItems) {
    addExtraToolItems(extraToolItems);
  }

  function addExtraToolItems(extraToolItems) {
    extraToolItems.forEach(function (moduleToolItems) {
      for (const key in moduleToolItems) {
        let targetToolbar = toolbarItems[key];
        if (!targetToolbar) {
          throw new Error("Invalid target toolbar: " + key);
        }
        moduleToolItems[key].forEach(function (toolItem) {
          toolItem = new TooItemModel(toolItem);
          targetToolbar.addItem(toolItem);
        });
      }
    });
  }

  return toolbarItems;
});
