csui.define('csui/controls/tablesettings/menu.item.views/table.settings.menu.item.view',[
  'csui/lib/underscore',
  'csui/lib/backbone',
  'csui/lib/marionette',
  'smart/utils/otwc.loader',
  'hbs!csui/controls/tablesettings/menu.item.views/impl/table.settings.menu.item',
], function (_, Backbone, Marionette, otwcLoader, template) {
  'use strict';
  const TableSettingsMenuItemView = Marionette.ItemView.extend({
    template: template,
    tagName: 'otc-menuitem',

    constructor: function TableSettingsMenuItemView(options) {
      // check mandatory parameters
      if (!options) {
        throw new Error('options object is mandatory for TableSettingsMenuItemView');
      }

      Marionette.ItemView.prototype.constructor.call(this, options);
      this.listenTo(this.model, 'change', this.render);
    },

    events: {
      'item-click': 'onClicked',
    },

    onClicked: function (event) {
      this.trigger('selected:menuitem', {});
    },

  });
  return TableSettingsMenuItemView;
});
